INSERT INTO envoutement (id_envoutement, nom, cout, effet, prerequis, danger)
VALUES
    (1, 'L''envoûtement des Ombres', '4', 'L''envoûtement des ombres crée des murmures dans les ténèbres et des silhouettes dans les coins. Le sujet doit faire des jets de vigilance au hasard avec un SD non spécifié, apercevant toujours quelque chose ou quelqu''un du coin de l’œil. Les jets de vigilance ne sont jamais pour une menace réelle, juste des visions.  Le sujet doit apporter un bol d''eau pure, une branche de myrte blanc et une bouteille d''encre dans une clairière lors d’une lune croissante. Quand la lune est au plus haut, le sujet doit verser l’encre dans l’eau, tremper la branche dans le mélange et asperger des gouttelettes en cercle autour de lui tout en retenant sa respiration.', 'Un bol d''eau pure, une branche de myrte blanc, une bouteille d''encre, une clairière, une lune croissante', 'Faible'),
    (2, 'La démangeaison éternelle', '4', 'La démangeaison éternelle fait pousser des pustules qui grattent et brûlent sur les parties intimes du sujet. La démangeaison n''inflige pas de dégâts, mais dérange constamment, ce qui inflige un malus de -1 à toutes les tâches. En plus du -1, la cible a un malus de -5 en séduction une fois dans "la chambre à coucher".    Le sujet doit rassembler 1 dose de sclérodermie, de petite ciguë et de bryone. Il doit allumer un feu de camp et faire un bouquet avec les herbes. Quand tout est prêt, le sujet doit embraser les herbes et effriter les cendres chaudes sur la zone atteinte tout en récitant une série de mots magiques.', '1 dose de sclérodermie, 1 dose de petite ciguë, 1 dose de bryone, un feu de camp', 'Faible'),
    (3, 'La chance démoniaque', '8', 'La chance démoniaque tourmente le sujet avec des touches de mauvaise fortune. Dans des situations très stressantes, comme un combat ou en effectuant une tâche avec un délai très court ou un SD supérieur à 15, le sujet fait un échec critique sur un 1 ou 2 naturel.', 'Un clou en argent, 2 doses d''aconit, une mèche de cheveux d''une vierge', 'Modéré'),
    (4, 'Le cauchemar', '8', 'Le cauchemar fait revivre au sujet le même cauchemar horrifique.Chaque nuit, le sujet doit faire un jet de résistance à la contrainte avec un SD égal au jet d''envoûtement du lanceur pour lancer cet envoûtement. En cas de réussite, le sujet parvient à dormir une nuit complète, bien qu''elle ne soit pas reposante. En cas d’échec, il dort à peine et ne régénère pas d''END ou de PS durant la nuit. S’il échoue trois nuits d’affilée, il réduit de moitié son endurance et a un malus de -2 à toutes ses actions jusqu’à pouvoir faire une nuit complète.', '5 bougies, 5 os de bête, 1 minerai luisant', 'Modéré'),
    (5, 'Le baiser de Pesta', '12', 'Le baiser de Pesta ôte au sujet sa capacité de combattre les maladies et sa résistance à la nausée. À chaque fois que le sujet est en contact avec une personne malade, il a 75% de chance d’attraper la maladie. À chaque fois que il sent quelque chose de nauséabond, même légèrement, il doit réussir un jet de résilience avec un SD 16 ou être nauséeux.', '3 doses d''argile alluviale, 1 dose de charbon, 3 doses de résine, 1 dose de poussière imprégnée', 'Élevé'),
    (6, 'L''envoûtement de la bête', '12', 'L''envoûtement de la bête rend la cible répugnante aux yeux des animaux et des bêtes. Dès que la cible s’approche d’un animal à moins de 10m, ce dernier réagira mal au sujet, ce qui lui inflige un malus de -3 en survie en ce qui concerne le dressage des animaux. À chaque fois que le sujet s’approche d’un animal à moins de 10m, il y a 50% de chance pour que l’animal attaque.', 'Un petit animal vivant, 2 doses de gui, une dose de phosphore, 2 doses d''œil de corbeau, 3 doses de racine de mandragore', 'Élevé');
INSERT INTO magie (id_magie, nom, cout, effet, portee, duree, nature, niveau, contre, type) VALUES
(1, 'Compas magique', '3 END', 'Le compas magique permet de déterminer instantanément la direction vers un endroit où vous êtes déjà allée auparavant. Sinon, le sort indique le nord.', 'Personnelle', '1D6 heure', 'Mixte', 'Sort de novice', '', 'Sort'),
(2, 'Dissipation', 'Variable', 'Dissipation met fin à un sort, un rituel ou une malédiction en cours dans sa portée. Ce sort permet d’annuler une magie qui dure et peut être utilisé comme une action défensive pour bloquer une attaque magique avec ou sans composants. Pour annuler un effet magique, vous devez dépenser la moitié des points de Résilience utilisés par le lanceur et réussir un jet d’Incantation en opposition à son jet pour lancer le sort.', '10 m', 'Instantané', 'Mixte', 'Sort de novice', 'Incantation', 'Sort'),
(3, 'Glamour', '5 END', 'Glamour vous permet de mettre une illusion autour de vous qui vous fait paraître éblouissant. Ce sort vous donne un bonus de +3 en Séduction, Charisme et Commandement.', 'Personnelle', '1D6 heures', 'Mixte', 'Sort de novice', '', 'Sort'),
(4, 'Invocation de bâton', '2 END', 'Invocation de bâton vous permet de dématérialiser votre bâton et de le téléporter à un endroit où vous avez été présent au cours du dernier jour. Vous pouvez lancer à nouveau le sort pour faire revenir le bâton à vous.', '', 'Instantané', 'Mixte', 'Sort de novice', '', 'Sort'),
(5, 'Manipulation de l''esprit', '3 END', 'Manipulation de l’esprit vous permet de forcer votre cible à ressentir l’une de ces émotions pendant la durée du sort : haine, amour, dépression ou euphorie.', '5 m', '1D10 rounds', 'Mixte', 'Sort de novice', 'Résistance à la magie', 'Sort'),
(6, 'Miroir d''Afan', '3 END', 'Inventé par le talentueux magicien Aedirnien Afan de Guletta, le miroir d''Afan crée 1D10 copies illusoires du lanceur. Ces copies sont intangibles, mais impossibles à différencier du lanceur, qui les contrôle par l’esprit. Contrôler ces copies ne demande pas d’action, mais elles ne peuvent pas se déplacer au-delà de la portée du dort.', '10 m', 'Actif (2 END)', 'Mixte', 'Sort de novice', '', 'Sort'),
(7, 'Poussière aveuglante', '3 END', 'La poussière aveuglante vous permet de lancer une poussière magique dans les yeux d’une cible afin de l’aveugler pour la durée du sort.', '4 m', '1D10 rounds', 'Mixte', 'Sort de novice', 'Esquive ou Blocage', 'Sort'),
(8, 'Télépathie', '2 END', 'Télépathie vous permet de communiquer par télépathie avec une personne pendant la durée du sort, sans barrière de langage.', '10 m', 'Actif (1 END)', 'Mixte', 'Sort de novice', '', 'Sort'),
(9, 'Cenlly Graig', '3 END', 'Cenlly Graig lance des pierres acérées sur votre adversaire. Lors de votre jet, pour chaque point qui dépasse la défense de votre adversaire (maximum 10), vous infligez 1D6 points de dégâts. Chaque lancer compte comme une attaque à part entière.', '5 m', 'Instantané', 'Terre', 'Sort de novice', 'Esquive ou Blocage', 'Sort'),
(10, 'Codi Bywyd', '2 END', 'Codi Bywyd permet de faire parvenir à maturité une graine en l’espace d’un round.Cela permet de faire pousser des herbes et des plantes alchimiques, mais rien de plus grand comme un arbre.', '4 m', 'Instantané', 'Terre', 'Sort de novice', '', 'Sort'),
(11, 'Diagnostic', '3 END', 'Diagnostic permet d’évaluer rapidement la santé d’une personne et de déterminer combien de points de santé elle a, ses blessures et si elle est malade ou empoisonnée.', '5 m', 'Instantané', 'Terre', 'Sort de novice', '', 'Sort'),
(12, 'Pic terrestre', '5 END', 'Pic terrestre crée une stalagmite inclinée de manière à pouvoir poignarder une cible. Le pic inflige 5D6 points de dégâts et reste en place jusqu’à être détruit. Il peut être détruit en lui infligeant 20 points de dégâts.', '6 m', 'Instantané', 'Terre', 'Sort de novice', 'Esquive ou Blocage', 'Sort'),
(13, 'Plume de Luthien', '2 END', 'Nommé ainsi d’après son créateur, Luthien de Ebbing, Plume de Luthien peut graver des écritures ou des dessins sur n’importe quelle surface solide. Le sort ne peut pas être utilisé sur une créature vivante.', '1 m', 'Instantané', 'Terre', 'Sort de novice', '', 'Sort'),
(14, 'Prison de Talfryn', '3 END', 'Prison de Talfryn tient son nom de Talfryn de Nazair, un chevalier traître qui a été piégé trois jours durant dans le jardin du magicien Drystan. Le sort permet d’empêcher une cible dans des racines. Il faut 15 points de dégâts pour détruire les racines. Autrement, pour s’en échapper, il faut un jet d’esquive ou d’évasion avec un SD égal à votre résultat pour lancer le sort.', '10 m', 'Jusqu''à destruction', 'Terre', 'Sort de novice', 'Esquive', 'Sort'),
(15, 'Soins magiques', '5 END', 'Soins magique stimule la régénération naturelle d’une cible en lui soignant 3 points de dégâts par round. L’effet dure pendant la durée du sort. Sinon, ce sort peut être utilisé plusieurs reprises pour soigner une blessure critique.', '2 m', '1D10 rounds', 'Terre', 'Sort de novice', '', 'Sort'),
(16, 'Soufle de Korath', '2 END', 'Souffle de Korath démolit une surface de terre ou de pierre proche et pulvérise du sable brûlant dans un cône de 3m devant le lanceur. Les adversaires dans cette zone qui ratent leur défense sont aveuglés pour 1D6 rounds.', 'Cône de 3 m', 'Instantané', 'Terre', 'Sort de novice', 'Esquive ou Blocage', 'Sort'),
(17, 'Abri d''Urien', '3 END', 'Abri d''Urien, créé par le magicien de l''air Urien de Cidari, permet d''annuler les effets d''un temps hostile dans un rayon de 8 m autour du lanceur. Cela annule la chaleur et le froid extrême, la pluie et la neige.', 'Rayon de 8 m', '1D6 heures', 'Air', 'Sort de novice', '', 'Sort'),
(18, 'Adenydd', '4 END', 'Adenydd vous allège légèrement et créé une trajectoire de descente lorsque vous chutez. Ce qui signifie que pour 2 m de chute, vous avancez de 2 m dans une direction. Si vous touchez terre avant la fin du sort, vous ne subirez aucun dégâts.', 'Personnelle', 'Actif (2 END)', 'Air', 'Sort de novice', '', 'Sort'),
(19, 'Air frais', '2 END', 'Air frais dégage une zone d''un rayon de 4 m autour de vous de tout poison, fumée ou autre air vicié pendant la durée du sort.', 'Rayon de 4 m', 'Actif (2 END)', 'Air', 'Sort de novice', '', 'Sort'),
(20, 'Poche d''air', '3 END', 'Poche d''air créé une poche d''air frais sous l''eau ou dans tout autre endroit  où il n''y a normalement pas d''air respirable. La poche fait un rayon de 1 m pendant toute la durée du sort.', '12 m', '2D10 rounds', 'Air', 'Sort de novice', '', 'Sort'),
(21, 'Rafale de Bronwyn', '2 END', 'Rafale de Bronwyn tire son nom du mage et pillard skellige, Bronwyn Œil-Sûr. Le sort permet de faire reculer une cible d''autant de mettre que le nombre de points supérieurs à la défense de l''adversaire sur votre jet. Cette attaque n''inflige que 1D6 points de dégâts, mais si votre adversaire percute quelque chose, il prend des dégâts d''éperonnage.', '2 m', 'Instantané', 'Air', 'Sort de novice', 'Esquive', 'Sort'),
(22, 'Télékinésie', '3 END', 'Télékinésie permet de soulever et manipuler un objet (jusqu''à 5 ENC par niveau d''Incantation) comme si vous le teniez.', '5 m', 'Actif (2 END)', 'Air', 'Sort de novice', '', 'Sort'),
(23, 'Tempête statique', '5 END', 'Ice cream candy cotton candy soufflé ice cream toffee jelly topping. Marzipan dessert cake jelly cotton candy. Bear claw bonbon cheesecake sweet cotton candy.', 'Rayon de 5 m', '2D6 rounds', 'Air', 'Sort de novice', '', 'Sort'),
(24, 'Zéphyr', '5 END', 'Zéphyr permet de faire éclater une rafale de vent qui repousse quiconque se trouve dans un rayon de 2 m autour de vous, d''autan de mètre que le nombre de points supérieurs à sa défense sur votre jet. Cette attaque n''inflige que 1D6 points de dégâts, mais si votre adversaire percute quelque chose, il subit des dégâts d''éperonnage.', 'Rayon de 2 m', 'Instantané', 'Air', 'Sort de novice', '', 'Sort'),
(25, 'Aenye', '5 END', 'Aenye permet de lancer une boule de feu pur sur un adversaire à portée du sort. Cette boule de feu inflige 4D6 points de dégâts et à 75% de chances de mettre le feu à la cible.', '12 m', 'Instantané', 'Feu', 'Sort de novice', 'Esquive ou Blocage', 'Sort'),
(26, 'Aine Verseos', '1 END', 'Aine Verseos créé une zone de lumière vive dans un rayon de 4 m autour de vous.', '4 m', 'Actif (2 END)', 'Feu', 'Sort de novice', '', 'Sort'),
(27, 'Attiser les flammes', '3 END', 'Cotton candy cotton candy wafer ice cream jelly beans lollipop cookie brownie. Oat cake jelly-o sweet bonbon gummies cheesecake. Muffin jelly-o gummies lemon drops tart shortbread pie cotton candy. Jelly beans pie marshmallow marzipan candy.', '10 m', 'Actif (2 END)', 'Feu', 'Sort de novice', '', 'Sort'),
(28, 'Éclat magique', '2 END', 'Éclat magique créé une lumière vive au-dessus de votre tête. Quiconque se trouve dans un rayon de 8 m doit faire un jet de Résistance à la magie ou être aveuglé pendant 1D6 rounds. Cet éclat est visible à 10 Km.', '8 m', 'Instantané', 'Feu', 'Sort de novice', 'Résistance à la magie', 'Sort'),
(29, 'Marque incandescente', '4 END', 'Marque incandescente permet de marquer une cible d''un simple symbole ou mot, à n''importe quel endroit exposé de son corps. Cela inflige 1D6 points de dégâts à la cible et laisse une grande cicatrice permanente.', '8 m', 'Instantané', 'Feu', 'Sort de novice', 'Bouclier magique', 'Sort'),
(30, 'Poigne de Cadfan', '4 END', 'Poigne de Cadfan, d''après le magicien et forgeron Cadfan de Ebbing, permet de surchauffer un objet en métal, de manière à le rendre impossible à tenir en main et obligeant son porteur à le lâcher ou à subir 2D6 points de dégâts au membre qui le tient. Il est également possible de chauffer une arme pour lui octroyer un bonus de chauffer un bonus de +2D6 dégâts et 50% de chances de mettre le feu à une cible.', '8 m', '1D6 rounds', 'Feu', 'Sort de novice', '', 'Sort'),
(31, 'Tanio Ilchar', '3 END', 'Tanio Ilchar créé une explosion de feu dans une zone de 2 m sur 2 m. Il y a 100 % de chance d''enflammer une cible qui se trouve dans la zone.', '8 m', 'Instantané', 'Feu', 'Sort de novice', 'Esquive', 'Sort'),
(32, 'Vague de feu', '4 END', 'Vague de feu tire dans une direction un cône de feu de 3 m qui inflige 2D6 points de dégâts à quiconque ne peut pas esquiver ou bloquer et a 50% de chance d''enflammer une cible.', '3 m', 'Instantané', 'Feu', 'Sort de novice', 'Esquive ou Blocage', 'Sort'),
(33, 'Aire de glace', '2 END', 'Aire de glace permet de créer une zone de glace de 2 m². Quiconque traverse cette zone de glace faire une jet d’Athlétisme avec un SD égal à votre résultat d''Incantation ou déraper sur la glace.', '10 m', '2D10 rounds', 'Eau', 'Sort de novice', 'Esquive', 'Sort'),
(34, 'Averse', '2 END', 'Averse créé une zone d''un rayon de 10 m de pluie qui éteint n''importe quel feu qu''elle touche. Ce sort contrecarre les effets du feu.', '8 m', 'Actif (2 END)', 'Eau', 'Sort de novice', '', 'Sort'),
(35, 'Brouillard de Dormyn', '3 END', 'Inventé par Dormyn de Gemmery, Brouillard de Dormyn créé dans une zone d''un rayon de 10 m, centrée sur vous, un épais brouillard qui donne un malus de -3 en Vigilance à ceux qui s''y trouvent et limite la vision à 4 m.', '10 m', 'Actif (2 END)', 'Eau', 'Sort de novice', '', 'Sort'),
(36, 'Contrôle de l''eau', '5 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '10 m', 'Actif (2 END)', 'Eau', 'Sort de novice', 'SD déterminé par le MJ', 'Sort'),
(37, 'Grêle de Cary', '3 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '5 m', 'Instantané', 'Eau', 'Sort de novice', 'Esquive ou Blocage', 'Sort'),
(38, 'Malédiction de Sedna', '5 END', 'Appelé ainsi en référence aux eaux tumultueuses de l''Abysse de Sedna, considéré comme une destination suicidaire pour les bateaux, Malédiction de Sedna crée un puissant tourbillon sur une zone de 4 m. Quiconque se trouve dans les 5 m doit faire un jet de Natation ou être emporté sous l''eau. Il faut refaire un jet à chaque tour ou rester sous l''eau et commencer à suffoquer.', '12 m', 'Actif (2 END)', 'Eau', 'Sort de novice', 'Esquive', 'Sort'),
(39, 'Puro Dwr', '2 END', 'Puro Dwr permet de purifier 1m³ d''eau. Cela supprime le poison et la maladie, mais ça ne fera pas en sortir les créatures vivantes. S''il est lancé sur une petite portion d''une eau polluée, la zone visée recommencera à être polluée après la durée du sort.', '4 m', '1D10 rounds', 'Eau', 'Sort de novice', '', 'Sort'),
(40, 'Rhewi', '2 END', 'Rhewi crée une couche de glace autour d''une cible pour la durée du sort. La cible est considérée comme gelée. S''il est utilisé sur une cible non vivante, elle ne peut plus être manipulée ou déplacée.', '8 m', '1D10 rounds', 'Eau', 'Sort de novice', 'Esquive', 'Sort'),
(41, 'Illusion', '8 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '20 m', 'Actif (4 END)', 'Mixte', 'Sort de compagnon', 'Résistance à la magie', 'Sort'),
(42, 'Technique d''Eilhart', '12 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '3 m', 'Instantané', 'Mixte', 'Sort de compagnon', 'Résistance à la magie', 'Sort'),
(43, 'Téléportation', '10 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '', 'Instantané', 'Mixte', 'Sort de compagnon', '', 'Sort'),
(44, 'Rhwystr Graig', '15 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '20 m', 'Jusqu''à destruction', 'Terre', 'Sort de compagnon', '', 'Sort'),
(45, 'Séisme de Stammelford', '12 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '30 m', '1D10 rounds', 'Terre', 'Sort de compagnon', 'Esquive', 'Sort'),
(46, 'Théorie d''Elgan', '10 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '8 m', '2D10 rounds', 'Terre', 'Sort de compagnon', '', 'Sort'),
(47, 'Gwynt Troelli', '12 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', 'Rayon de 10 m', 'Actif (4 END)', 'Air', 'Sort de compagnon', '', 'Sort'),
(48, 'Suffocation', '14 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '10 m', 'Actif (4 END)', 'Air', 'Sort de compagnon', 'Résistance à la magie', 'Sort'),
(49, 'Tonnerre d''Alzur', '15 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '25 m', 'Instantané', 'Air', 'Sort de compagnon', 'Esquive', 'Sort'),
(50, 'Afflux de Demetia', '12 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '10 m', 'Actif (4 END)', 'Feu', 'Sort de compagnon', '', 'Sort'),
(51, 'Prise de Seirff', '10 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '10 m', '2D10 rounds', 'Feu', 'Sort de compagnon', 'Esquive', 'Sort'),
(52, 'Vortex enflammé', '15 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '10 m', 'Actif (4 END)', 'Feu', 'Sort de compagnon', 'Esquive', 'Sort'),
(53, 'Anialwch', '8 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '10 m', 'Instantané', 'Eau', 'Sort de compagnon', 'Résistance à la magie', 'Sort'),
(54, 'Grêle dévastatrice de Merigold', '15 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '30 m', 'Actif (4 END)', 'Eau', 'Sort de compagnon', 'Esquive', 'Sort'),
(55, 'Vague de Naglfar', '10 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', 'Rayon de 3 m', 'Instantané', 'Eau', 'Sort de compagnon', 'Esquive ou Blocage', 'Sort'),
(56, 'Commandement psychique', '25 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '10 m', 'Jusqu''à la fin de la tâche', 'Mixte', 'Sort de maître', 'Résistance à la magie', 'Sort'),
(57, 'Portail', '22 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '10 m', 'Actif (6 END)', 'Mixte', 'Sort de maître', '', 'Sort'),
(58, 'Polymorphisme', '22 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', 'Personnelle', 'Jusqu''au nouveau lancement du sort', 'Terre', 'Sort de maître', '', 'Sort'),
(59, 'Transmutation', '25 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '2 m', 'Permanent', 'Terre', 'Sort de maître', '', 'Sort'),
(60, 'Derviche', '22 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', 'Rayon de 2 m', 'Actif (6 END)', 'Air', 'Sort de maître', 'Esquive', 'Sort'),
(61, 'Orage', '25 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '20 m', 'Actif (6 END)', 'Air', 'Sort de maître', 'Esquive', 'Sort'),
(62, 'Effet mirroir', '25 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '20 m', '2D6 rounds', 'Feu', 'Sort de maître', 'Esquive ou Blocage', 'Sort'),
(63, 'Feu de Melgar', '25 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', 'Rayon de 40 m', '2D6 rounds', 'Feu', 'Sort de maître', 'Esquive ou Blocage', 'Sort'),
(64, 'Séparation des eaux', '25 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', 'Rayon de 10 m', 'Actif (6 END)', 'Eau', 'Sort de maître', '', 'Sort'),
(65, 'Tryferi Gaeaf', '22 END', 'Donut gummies chocolate topping brownie apple pie. Chupa chups wafer biscuit marshmallow dessert macaroon chocolate bear claw. Fruitcake jelly-o apple pie bonbon macaroon sweet roll ice cream lemon drops chupa chups.', '20 m', '1D10 rounds', 'Eau', 'Sort de maître', 'Esquive ou Blocage', 'Sort'),
(66, 'Yrden', 'Variable', 'Yrden dessin au sol autour de vous un grand cercle magique. Tout ce qui entre dans le cercle subit un malusà la VIT et au RÉF.', 'rayon de 3 m', '5 round', 'Mixte', 'Signe de base', '', 'Signe'),
(67, 'Aard', 'Variable', 'Aard déclenche une vague de force télékinésique qui stupéfie les créatures avec 10% de chance pour chaque point d''END dépensé.', 'Cône de 2 m', 'instantané', 'Air', 'Signe de base', 'Esquive', 'Signe'),
(68, 'Quen', 'Variable', 'Quen crée un bouclier avec 5 points de santé par points d''END dépensé. Si vous échouez à vous défendre (ou que vous ne voulez/pouvez pas vous défendre) contre une attaque ou un effet infligeant des dégâts, ces dégâts sont infligés en priorité au bouclier Quen. Les dégâts létaux et non létaux réduisent d''autant les points de santé du bouclier. Si le bouclier Quen est réduit à 0 point de santé, les dégâts surnuméraires vous sont infligés et doivent pénétrer votre armure et votre éventuelle résistance aux dégâts afin d''impacter vos points de santés ou votre Endurance. Quen peut être utilisé pour se défendre contre les sorts pouvant être bloqués, mais est inefficace dans le cas contraire. Le signe ne protège pas non plus des dégâts infligés par un poison déjà absorbé/inoculé, une maladie ou la suffocation. Vous ne pouvez pas relancer à nouveau Quen tant que ses points de santé n''ont pas été épuisés ou qu''il ne s''achève (10 rounds).', 'personnelle', '10 rounds ou jusqu''à épuisement', 'Terre', 'Signe de base', '', 'Signe'),
(71, 'Contrôle de l''eau', '5 END', 'Contrôle de l''eau permet de contrôler la vitesse à laquelle un plan d''eau bouge et dans quelle direction il va pendant la durée du sort. On peut l''utiliser pour ralentir de moitié une cible qui nage, réduire de moitié la vitesse d''un navire ou ralentir ou arrêter le courant d''une rivière.', '10 m', 'Actif (2 END)', 'Eau', 'Sort de novice', '', 'Sort'),
(72, 'Grêle de Cary', '3 END', 'Nommé ainsi d''après son créateur, Carys de Cintra, ce sort projette des plombs de glace à très haute vitesse sur un adversaire. Pour chaque point que vous obtenez au-dessus de l''Esquive ou du Blocage de votre adversaire (maximum 5), vous infligez 1D6 points de dégâts et avez 25 % de chances de geler votre opposant. Chaque jet est une attaque unique pour déterminer les dégâts et leur localisation.', '5 m', 'instantané', 'Eau', 'Sort de novice', '', 'Sort'),
(74, 'Ami des espèces sauvage', '1 END', 'Ami des espèces sauvages octroie au lanceur un bonus de +3 en Survie pour dresser des animaux. L''invocation peut aussi apaiser un animal si le jet d''Incantation dépasse la VOL x 3 de l''animal.', 'Personelle ou 5 m', '1D6 heures', 'Aucun', 'Invocation novice de druide', 'Volonté de la créature x3', 'Invocation'),
(75, 'Don ce la nature', 'Variable', 'Don de la nature fait pousser une petite grappe de plantes comestibles dans n''importe quel sol. Ces plantes sont suffisantes pour nourrir autant de personnes pendant un jour que le nombre de points d''END dépensés.', '2 m', 'instantané', 'Aucun', 'Invocation novice de druide', NULL, 'Invocation'),
(76, 'Emblème de l''invisible', '2 END', 'En dessinant l''Emblème de l''invisible, vous couvrez une zone  de 3 m avec des branches, des feuillages et autres éléments naturels afin d''obtenir une couverture visuelle totale. Cela vous octroie un bonus de +5 à la Discrétion, mais immobilise ceux qui se trouvent dans la zone et l''invocation doit être relancée pour se découvrir. Vous pouvez tailler à travers les broussailles en leur infligeant 10 points de dégâts.', 'personnelle', 'jusqu''à dissipation', 'Aucun', 'Invocation novice de druide', NULL, 'Invocation'),
(77, 'Maladiction', 'Variable', 'Maladiction rend une cible malade. La maladie se manifeste différemment, selon comment les points de Résilience sont dépensés. Avec 2 points, la cible est pliée en deux parla toux et stupéfiée. Avec  4 points, la cible est gravement malade et étourdie.', '8 m', 'le jet de Résilence y met fin', 'Aucun', 'Invocation novice de druide', 'Résistance à la magie', 'Invocation'),
(78, 'Sang bouillonnant', '3 END', 'Sang bouillonnant provoque la rage chez un animal ou un monstre non sensible à l''encontre d''une cible. La créature attaquera la cible choisie jusqu''à la fin du sort.', '8 m', '1D10 rounds', 'Aucun', 'Invocation novice de druide', 'Volonté de la créature x3', 'Invocation'),
(79, 'Vision naturelle', '2 END', 'Vision naturelle permet de voir les créatures qui ne sont pas de ce royaume. Cela vous permet de voir les monstres à 50 m, même à travers les obstacles. Les monstres ainsi repérés apparaissent sous une version lumineuse d''eux même.', 'personelle', 'actif (1 END)', 'Aucun', 'Invocation novice de druide', NULL, 'Invocation'),
(80, 'Igni', 'Variable', 'Igni projette une vague d''étincelles et de feu qui inflige 1D6 points de dégâts par point d''END dépensé et à 50% de chance de mettre le feu à tout ce qu''elle touche. Igni inflige toujours ses dégâts au torse, à moins qu''il ne soit utilisé à bout portant. Lorsqu''Igni est utilisé à bout portant, peut prendre pour cible n''importe localisation.', 'Cône de 2 m', 'instantané', 'Feu', 'Signe de base', 'Esquive', 'Signe'),
(81, 'Axii', 'Variable', 'Axii étourdit un adversaire jusqu''à ce qu''il réussisse une jet de sauvegarde contre l''étourdissement avec un malus de -1. pour 2 points d''END supplémentaires dépensés, le jet de sauvegarde contre l''étourdissement est plus difficile de 1 point.', '8 m', 'jusqu''à s''en débarasser', 'Eau', 'Signe de base', '', 'Signe');
INSERT INTO rituel (id_rituel, nom, cout, effet, temps_preparation, sd, duree, composant, niveau)VALUES
(1, 'Rituel de magie', '3 END', 'Le Rituel de magie crée un cercle magique qui renforce la tolérance à la magie, en accordant un bonus au seuil de Vigueur égal à la moitié du niveau de Rituels du lanceur. Ce bénéfice est accordé à la première personne avec des capacité magique qui pénètre dans le cercle et se concentre dessus, et dure 5 heures. Autrement, le lanceur peut dépenser le cercle pour gagner 1D6/2 unités de cinquième essence.', '5 rounds', '15', 'une utilisation', '1 poussière imprégnée, 2 craies, 2 dose de soufre, 2 verres', 'Rituel de novice'),
(2, 'Hydromencie', '5 END', 'Hrydromencie permet de fixer une petite flaque d''eau pour y apercevoir un évènement  qui c''est passé au cours des deux derniers jours ou a lieu au moment même. Regarder un évènement du passé se fait sur le SD de base. Si vous essayez de voir un évènement qui se passe au moment même, augmentez le SDde 3. Si vous observez un évènement présent, si un magicien y est présent, il peut sentir l''augure avec un jet d''Exercice de la magie supérieur à votre jet de Rituels.', '5 rounds', '15 (18)', 'actif (2END)', 'une petite quantité d''eau ou un bol d''eau, 1 éclat de lune, 1 fruit de berbéris, 2 dose de cinquième essence, 2 perles, 2 pétales de myrte blanc.', 'Rituel de novice'),
(3, 'Pyromancie', '3 END', 'Pyromancie permet de fixer un feu et y observer des évènements qui se passent au même moment. Pyromancie est plus dangereux qu''Hydromancie, ce qui le rend plus difficile à maintenir et impossible à regarder à l''envers. Cependant, il es plus facile de voir des évènements présents. Tout comme avec Hydromencie, un mage que vous observez ainsi peut sentir l''augure avec un jet d''Exercice de la magie supérieur a votre jet de Rituels.', '5 rounds', '15', 'actif (4END)', 'un petit feu, 2 dose de cinquième essence, 2 dose de cendres, 2 dose de cire, 2 œils de corbeau, 5 calcium equun', 'Rituel de novice'),
(4, 'Message magique', '3 END', 'Message magique permet d''enregistrer un message de 5 minutes dans une gemme ou un bout de verre gravé d''un emblème magique. Vous pouvez déterminer jusqu''à trois déclencheurs spécifiques qui activeront le message. Une fois lu, le message reste en dormance jusqu''au prochain déclencheur. Quand il est déclenché, une illusion du lanceur apparaît et délivre le message. S''il est enregistré dans une gemme parfaite, le message est aussi clair que si le ritualiste était physiquement présent.', '5 rounds', '12', 'permanent', '1 dose de cinquième essence, 1 solution de mercure, 1 verre', 'Rituel de novice'),
(5, 'Rituel de purification', '3 END', 'Rituel de purification purifie le corps d''une cible de tout poison ou maladie. Quand il est activé, le lanceur fait un jet de Rituels contre un SD spécifique afin de nettoyer le corps de la cible. L''alcool et les drogues sont assez facile, avec un SD 12. Les poisons et les huiles sont plus difficiles, avec un SD 15. Les maladies graves sont très difficiles à purifier avec un SD 18. Rituel purificateur ne permet pas de soigner les épidémies telles que la catriona.', '5 rounds', 'variabl', 'instantané', '1 feuille de balisse, 1 liqueur, 1 œil de corbeau, 2 craies, 2 dose de gui', 'Rituel de novice');
